package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import com.ruoyi.medical.persistence.mapper.*;import java.io.*;import java.time.*;import java.util.*;
/** Irreversible one-time retirement; future boundary is explicit and immutable. Never edits the approved policy. */
public final class RuntimeRetentionDecisions {
 private final EnterpriseAccess access;private final RuntimeRetentionMapper mapper;private final PermissionMapper permissions;private final ResourceReadAuthority resources;private final RuntimeRetentionAuthority authority;private final RuntimeRetentionSchema schema;private final PermissionSchema json;
 public RuntimeRetentionDecisions(EnterpriseAccess access,RuntimeRetentionMapper mapper,PermissionMapper permissions,ResourceReadAuthority resources,RuntimeRetentionAuthority authority,RuntimeRetentionSchema schema,PermissionSchema json){this.access=access;this.mapper=mapper;this.permissions=permissions;this.resources=resources;this.authority=authority;this.schema=schema;this.json=json;}
 public JsonNode retire(ApplicationSessionIdentity.Verified actor,String context,String key,byte[] body){RuntimeRetentionSchema.key(key);return access.execute(actor,a->checked(()->{
  current(a,context);var request=schema.request("RetireRequest",body);RuntimeRetentionCancellation.requireNotCancelled(mapper,schema,a,"RETIRE",key,request);String id=request.required("policy_revision").textValue();var old=RuntimeRetentionAuthority.one(mapper.fixed(RuntimeRetentionAuthority.parameters("policyRevision",id)));authority.verify(old);resources.require(a,RuntimeRetentionAuthority.scope(a.context().tenant_id(),old.projectId()),"retention.approve","RUNTIME_RETENTION_APPROVAL");
  var previous=mapper.retirementByKey(Map.of("userId",a.actorId(),"key",key));if(previous.size()>1)fail();if(!previous.isEmpty()){var row=previous.get(0);if(!row.createdBy().equals(a.actorId())||!row.key().equals(key))fail();var d=authority.verifyRetirement(row);if(!schema.hash(request).equals(d.required("original_request_sha256").textValue()))throw new TenantAccessException(ErrorCode.IDEMPOTENCY_CONFLICT);return d.required("operation_receipt");}
  return record(a,old,request.required("expected_revision").textValue(),request.required("effective_at").textValue(),null,request,key,UUID.randomUUID().toString(),null);
 }));}
 JsonNode replace(EnterpriseAccess.Admission a,JsonNode request,String newPolicy,String key,String operation,JsonNode receipt)throws IOException{
  if(request.required("replaces").isNull())return null;var replacement=request.required("replaces");var old=RuntimeRetentionAuthority.one(mapper.fixed(RuntimeRetentionAuthority.parameters("policyRevision",replacement.required("policy_revision").textValue())));authority.verify(old);
  if(!Objects.equals(old.projectId(),RuntimeRetentionAuthority.nullable(request.required("project_id")))||!old.classification().equals(request.required("classification").textValue())||old.policyRevision().equals(newPolicy))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
  return record(a,old,replacement.required("expected_revision").textValue(),request.required("effective_from").textValue(),newPolicy,request,key,operation,receipt);
 }
 private JsonNode record(EnterpriseAccess.Admission a,RuntimeRetentionMapper.Row old,String expected,String effective,String replacement,JsonNode request,String key,String operation,JsonNode originalReceipt)throws IOException{
  var state=authority.lifecycle(old);if(!"1".equals(expected)||!expected.equals(state.revision())||state.retiredAt()!=null)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
  var now=permissions.databaseTime();Instant boundary=Instant.parse(effective);if(boundary.isBefore(now.toInstant(ZoneOffset.UTC)))throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);
  var grant=resources.require(a,RuntimeRetentionAuthority.scope(a.context().tenant_id(),old.projectId()),"retention.approve","RUNTIME_RETENTION_APPROVAL");String decision=UUID.randomUUID().toString(),audit=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();
  var receipt=json.object();receipt.put("schema_version","1.0.0");receipt.put("decision_id",decision);receipt.put("policy_revision",old.policyRevision());receipt.put("operation_id",operation);receipt.put("request_body_sha256",schema.hash(request));receipt.put("effective_at",effective);receipt.put("revision","2");receipt.put("status","RETIREMENT_RECORDED");schema.validate("RetireReceipt",receipt);
  var d=json.object();d.put("schema_version","1.0.0");d.put("tenant_id",a.context().tenant_id());d.set("project_id",json.tree(old.projectId()));d.put("decision_id",decision);d.put("policy_revision",old.policyRevision());d.set("replacement_policy_revision",json.tree(replacement));d.put("operation_id",operation);d.put("operation_target_id",replacement==null?old.policyRevision():replacement);d.put("kind",replacement==null?"DISABLE":"REPLACE");d.set("original_request",request);d.put("original_request_sha256",schema.hash(request));d.set("operation_receipt",replacement==null?receipt:originalReceipt);d.put("effective_at",effective);d.put("expected_revision","1");d.put("resulting_revision","2");d.put("decided_by",a.actorId());d.put("decided_at",now.toInstant(ZoneOffset.UTC).toString());d.set("authority_grant",json.tree(Map.of("grant_id",grant.grantId(),"revision",grant.revision().toString())));d.put("audit_id",audit);d.put("event_id",event);schema.validate("Retirement",d);
  var v=new HashMap<String,Object>();v.put("userId",a.actorId());v.put("projectId",old.projectId());v.put("policyRevision",old.policyRevision());v.put("decisionId",decision);v.put("operationId",operation);v.put("key",key);v.put("kind",replacement==null?"DISABLE":"REPLACE");v.put("requestHash",schema.hash(request));v.put("fixedJson",schema.canonical(d));v.put("contentHash",schema.hash(d));v.put("receiptJson",schema.canonical(receipt));v.put("manifest",schema.manifest());v.put("classification",old.classification());v.put("now",now);v.put("effectiveAt",LocalDateTime.ofInstant(boundary,ZoneOffset.UTC));v.put("expected",expected);
  var witness=authority.retirementWitness(d);
  if(replacement==null)one(mapper.insertRetireOperation(v));one(permissions.saveAudit(a.actorId(),old.projectId(),audit,"runtime.retention.retired",schema.canonical(witness),operation,schema.manifest(),old.classification()));one(permissions.saveEvent(a.actorId(),event,old.policyRevision(),"2","runtime.retention.retired",schema.canonical(witness)));one(mapper.insertRetirement(v));one(mapper.retireState(v));authority.lifecycle(old);
  if(!grant.equals(resources.require(a,RuntimeRetentionAuthority.scope(a.context().tenant_id(),old.projectId()),"retention.approve","RUNTIME_RETENTION_APPROVAL")))throw new TenantAccessException(ErrorCode.SCOPE_STALE);return receipt;
 }
 public JsonNode recover(ApplicationSessionIdentity.Verified actor,String context,String key){RuntimeRetentionSchema.key(key);return access.execute(actor,a->checked(()->{current(a,context);var rows=mapper.retirementByKey(Map.of("userId",a.actorId(),"key",key));if(rows.size()>1)fail();if(rows.isEmpty())return json.object().put("schema_version","1.0.0").put("status","NOT_FOUND").putNull("receipt");var row=rows.get(0);if(!row.createdBy().equals(a.actorId())||!row.key().equals(key))fail();resources.require(a,RuntimeRetentionAuthority.scope(a.context().tenant_id(),row.projectId()),"retention.read","RUNTIME_RETENTION_READING");var d=authority.verifyRetirement(row);var result=json.object().put("schema_version","1.0.0").put("status","FOUND");result.set("receipt",d.required("operation_receipt"));return result;}));}
 private interface Work<T>{T run()throws IOException;}private static <T>T checked(Work<T> w){try{return w.run();}catch(IOException e){throw new SchemaRejection(ErrorCode.CONTENT_MISMATCH);}}private static void current(EnterpriseAccess.Admission a,String c){if(!a.context().context_revision().equals(c))throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);}private static void one(int n){if(n!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static void fail(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
